  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'أي الآتي صحيح وفق النص؟', '["المشكلات والعقبات ملح الحياة", "المشكلات والعقبات من ضروريات الحياة", "المشكلات والعقبات من منغصات الحياة", "العقبات والصعوبات غير ضرورية"]'::jsonb, 0, 'النص يرى أن الحياة بلا عقبات مملة ولا قيمة لها، فالعقبات هي ما يعطيها طعمها؛ أي إنها ملح الحياة.', NULL, 'ad070926-2026-4c00-9d00-070920260001', 'e1a90703-2026-4c00-9d00-000000000003', 'لو خلت الحياة من العقبات والعوائق لأصبحت مملة؛ فمحاولة تخطي العقبات والعوائق هي التي تولّد الشعور بالإثارة والفوز. فالحياة بلا مشقة ولا متاعب تصبح حياة لا قيمة لها، ويجب أن يكون هناك متاعب، ثم مثابرة لتخطيها، ثم الفوز بالحياة.', 1, 'active', false);
