  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'نستنتج من ترتيب النص أن الحياة عبارة عن:', '["مشقة ومتاعب – مثابرة – الفوز بالحياة", "الفوز بالحياة – مشقة ومتاعب – مثابرة", "مثابرة – الفوز بالحياة – مشقة ومتاعب", "الفوز بالحياة – مثابرة – مشقة ومتاعب"]'::jsonb, 0, 'النص يرتبها صراحة: متاعب، ثم مثابرة لتخطيها، ثم الفوز بالحياة.', NULL, 'ad070926-2026-4c00-9d00-070920260001', 'e1a90703-2026-4c00-9d00-000000000003', 'لو خلت الحياة من العقبات والعوائق لأصبحت مملة؛ فمحاولة تخطي العقبات والعوائق هي التي تولّد الشعور بالإثارة والفوز. فالحياة بلا مشقة ولا متاعب تصبح حياة لا قيمة لها، ويجب أن يكون هناك متاعب، ثم مثابرة لتخطيها، ثم الفوز بالحياة.', 3, 'active', false);
