  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'العلاقة بين (المشقة) و(المتاعب):', '["ترادف", "تتابع", "تضاد", "تمثيل"]'::jsonb, 0, 'المشقة والمتاعب لفظان بمعنى واحد تقريبًا، فالعلاقة ترادف.', NULL, 'ad070926-2026-4c00-9d00-070920260001', 'e1a90703-2026-4c00-9d00-000000000003', 'لو خلت الحياة من العقبات والعوائق لأصبحت مملة؛ فمحاولة تخطي العقبات والعوائق هي التي تولّد الشعور بالإثارة والفوز. فالحياة بلا مشقة ولا متاعب تصبح حياة لا قيمة لها، ويجب أن يكون هناك متاعب، ثم مثابرة لتخطيها، ثم الفوز بالحياة.', 4, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'العنوان الأنسب للنص:', '["وجود العوائق والعقبات ضروري من أجل الحياة", "وجود العقبات وتخطيها ضروري من أجل الحياة", "الحياة بلا عقبات", "الفوز بالحياة سهل"]'::jsonb, 1, 'النص لا يكتفي بوجود العقبات بل يجعل تخطيها هو ما يولّد الإثارة والفوز؛ فالعنوان الجامع: وجود العقبات وتخطيها.', NULL, 'ad070926-2026-4c00-9d00-070920260001', 'e1a90703-2026-4c00-9d00-000000000003', 'لو خلت الحياة من العقبات والعوائق لأصبحت مملة؛ فمحاولة تخطي العقبات والعوائق هي التي تولّد الشعور بالإثارة والفوز. فالحياة بلا مشقة ولا متاعب تصبح حياة لا قيمة لها، ويجب أن يكون هناك متاعب، ثم مثابرة لتخطيها، ثم الفوز بالحياة.', 5, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'الترتيب الزمني لتخطي العقبات هو:', '["تخطي العقبات – الإثارة – الشعور بالفوز", "الإثارة – تخطي العقبات – الشعور بالفوز", "الشعور بالفوز – الإثارة – تخطي العقبات", "الإثارة – الشعور بالفوز – تخطي العقبات"]'::jsonb, 0, 'النص يقول إن محاولة تخطي العقبات هي التي تولّد الإثارة ثم الشعور بالفوز، فالتخطي أولًا ثم الإثارة ثم الفوز.', NULL, 'ad070926-2026-4c00-9d00-070920260001', 'e1a90703-2026-4c00-9d00-000000000003', 'لو خلت الحياة من العقبات والعوائق لأصبحت مملة؛ فمحاولة تخطي العقبات والعوائق هي التي تولّد الشعور بالإثارة والفوز. فالحياة بلا مشقة ولا متاعب تصبح حياة لا قيمة لها، ويجب أن يكون هناك متاعب، ثم مثابرة لتخطيها، ثم الفوز بالحياة.', 6, 'active', false);
