  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الحساب', 'اختيار من متعدد', 'ما أكبر عدد يمكن تكوينه من الأرقام ١، ٢، ٣، ٥ بحيث يكون أكبر من ١٠٠٠ ودون تكرار أي رقم؟', '["٥٢٣١", "٣٥٢١", "٥٣١٢", "٥٣٢١"]'::jsonb, 3, 'للحصول على أكبر عدد نرتب الأرقام تنازليًا من اليسار: ٥ ثم ٣ ثم ٢ ثم ١، فالعدد ٥٣٢١.', NULL, 'ad070926-2026-4c00-9d00-070920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الحساب', 'اختيار من متعدد', 'مكعب ٣ من أوجهه باللون الأزرق، ووجهان باللون الأحمر، ووجه واحد باللون الأصفر. أوجد نسبة الأوجه الحمراء.', '["١/٦", "٣/٥", "١/٣", "٢/٣"]'::jsonb, 2, 'للمكعب ٦ أوجه، والحمراء منها ٢، فالنسبة = ٢/٦ = ١/٣.', NULL, 'ad070926-2026-4c00-9d00-070920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الحساب', 'اختيار من متعدد', 'أوجد قيمة: (٤ + ٣) × ٢ − ٤ = .....', '["١٢", "٤", "٥", "١٠"]'::jsonb, 3, 'القوس أولًا: ٤ + ٣ = ٧، ثم الضرب: ٧ × ٢ = ١٤، ثم الطرح: ١٤ − ٤ = ١٠.', NULL, 'ad070926-2026-4c00-9d00-070920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الحساب', 'اختيار من متعدد', 'قارن بين:
القيمة الأولى: (٢٦ − ١٦) × (١٦ − ٦) × (١٦ − ٧)
القيمة الثانية: ٣٦ ÷ ٠٫٠٤', '["القيمة الأولى أكبر", "القيمة الثانية أكبر", "القيمتان متساويتان", "المعطيات غير كافية"]'::jsonb, 2, 'الأولى: ١٠ × ١٠ × ٩ = ٩٠٠. الثانية: ٣٦ ÷ ٠٫٠٤ = ٣٦٠٠ ÷ ٤ = ٩٠٠. متساويتان.', NULL, 'ad070926-2026-4c00-9d00-070920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'المثلثان أ ب ج وهـ د و متطابقان بحيث أ ب = هـ د، وأ ج = هـ و، وب ج = د و. في المثلث هـ د و: قياس الزاوية هـ = ٣٠° وقياس الزاوية د = ٢٧°. قارن بين:
القيمة الأولى: قياس الزاوية ج
القيمة الثانية: ١١١', '["القيمة الأولى أكبر", "القيمة الثانية أكبر", "القيمتان متساويتان", "المعطيات غير كافية"]'::jsonb, 0, 'الزاوية و في المثلث الثاني = ١٨٠ − ٣٠ − ٢٧ = ١٢٣°. وبالتطابق تقابل الزاوية ج الزاوية و (لأن الضلعين المحيطين بهما متناظران)، فزاوية ج = ١٢٣° وهي أكبر من ١١١.', NULL, 'ad070926-2026-4c00-9d00-070920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الإحصاء والاحتمالات', 'اختيار من متعدد', 'في رسم دائري لتقديرات ٦٠٠ طالب: ممتاز ٤٥°، جيد جدًا ٧٥°، جيد ١٢٠°، مقبول ٨٠°، ضعيف ٤٠°. إذا كان ترتيب أحمد ٢٢٢ عند ترتيب الطلاب من الأعلى تقديرًا إلى الأدنى، فما تقديره؟', '["مقبول", "جيد", "جيد جدًا", "ممتاز"]'::jsonb, 1, 'عدد طلاب كل تقدير = ٦٠٠ × (الزاوية ÷ ٣٦٠): ممتاز ٧٥، جيد جدًا ١٢٥ (المجموع التراكمي ٢٠٠)، جيد ٢٠٠ (التراكمي ٤٠٠). الترتيب ٢٢٢ يقع بين ٢٠١ و٤٠٠، أي في فئة جيد.', NULL, 'ad070926-2026-4c00-9d00-070920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الإحصاء والاحتمالات', 'اختيار من متعدد', 'في رسم دائري لأنواع النفايات: الورقية ٣٥٪ والمعدنية ١٥٪ والباقي بلاستيكية وطعام. إذا تضاعفت نسبة النفايات المعدنية على حساب الورقية، فكم تصبح نسبة النفايات الورقية؟', '["٣٠٪", "٢٥٪", "٢٠٪", "١٥٪"]'::jsonb, 2, 'تضاعف المعدنية من ١٥٪ إلى ٣٠٪ يعني زيادة ١٥٪ تُؤخذ من الورقية: ٣٥ − ١٥ = ٢٠٪.', NULL, 'ad070926-2026-4c00-9d00-070920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'إذا كانت س وص زاويتين متكاملتين، وس وع زاويتين متتامتين، فأوجد ص + ع.', '["٢٧٠ − س", "٢٧٠ − ٢س", "٢٧٠ − ٣س", "٢٧٠ − ٤س"]'::jsonb, 1, 'ص = ١٨٠ − س (متكاملتان)، وع = ٩٠ − س (متتامتان)، فالمجموع ص + ع = ٢٧٠ − ٢س.', NULL, 'ad070926-2026-4c00-9d00-070920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'ربع دائرة نصف قطرها ٨. أوجد محيط هذا الربع.', '["١٦π + ١٦", "٤π + ١٦", "٨π + ١٦", "٦π + ١٦"]'::jsonb, 1, 'طول القوس = ربع محيط الدائرة = (٢π × ٨) ÷ ٤ = ٤π، ونضيف نصفي القطر المستقيمين ٨ + ٨ = ١٦، فالمحيط = ٤π + ١٦.', NULL, 'ad070926-2026-4c00-9d00-070920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'مستطيل أ ب ج د فيه أ د = ٦ سم، وت منتصف الضلع أ د، والمثلث ت ب ج متطابق الضلعين حيث ت ب = ت ج = ٥ سم. أوجد طول أ ب.', '["٦", "٢", "٤", "١"]'::jsonb, 2, 'أ ت = نصف أ د = ٣ سم. المثلث ت أ ب قائم الزاوية في أ (زاوية المستطيل)، فبفيثاغورس: أ ب = √(٥² − ٣²) = √١٦ = ٤ سم.', NULL, 'ad070926-2026-4c00-9d00-070920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'إذا كان محيط مثلث قائم الزاوية ٢٤، قارن بين:
القيمة الأولى: طول الوتر
القيمة الثانية: ٨', '["القيمة الأولى أكبر", "القيمة الثانية أكبر", "القيمتان متساويتان", "المعطيات غير كافية"]'::jsonb, 0, 'الوتر أطول أضلاع المثلث القائم، فهو أكبر من ثلث المحيط (٨) دائمًا؛ فلو كان الوتر ٨ أو أقل لكان مجموع الضلعين الآخرين ١٦ أو أكثر وكل منهما أقصر من الوتر، وهذا مستحيل. (مثال: المثلث ٦–٨–١٠ محيطه ٢٤ ووتره ١٠.)', NULL, 'ad070926-2026-4c00-9d00-070920260001', NULL, NULL, NULL, 'active', false);
END IF;
END
