-- مزامنة العداد مع الواقع
UPDATE leak_groups
SET question_count = (SELECT COUNT(*) FROM questions WHERE leak_group_id = 'ad070926-2026-4c00-9d00-070920260001')
WHERE id = 'ad070926-2026-4c00-9d00-070920260001';

-- تحقق نهائي
DO $chk$
DECLARE n INT; nq INT; nv INT; np INT;
BEGIN
  SELECT COUNT(*) INTO n FROM questions WHERE leak_group_id = 'ad070926-2026-4c00-9d00-070920260001';
  SELECT COUNT(*) INTO nq FROM questions WHERE leak_group_id = 'ad070926-2026-4c00-9d00-070920260001' AND section = 'quant';
  SELECT COUNT(*) INTO nv FROM questions WHERE leak_group_id = 'ad070926-2026-4c00-9d00-070920260001' AND section = 'verbal';
  SELECT COUNT(*) INTO np FROM questions WHERE leak_group_id = 'ad070926-2026-4c00-9d00-070920260001' AND passage_id IS NOT NULL;
  RAISE NOTICE 'إجمالي: % — كمي: % — لفظي: % — قطع: %', n, nq, nv, np;
  IF n <> 68 THEN RAISE EXCEPTION 'عدد الأسئلة % لا يطابق المتوقع 68', n; END IF;
  IF nq <> 32 OR nv <> 36 THEN RAISE EXCEPTION 'توزيع كمي/لفظي غير مطابق'; END IF;
END
$chk$;

COMMIT;